import {houseZones,calculateTransport,perimeterPoint,weightedResult,uniformEstimate,SOURCE_URL,RULE_VERSION} from './engine.mjs';
import {CALCULATORS,GROUPS,defaults,runCalculator,sourceLink,fmt,PERIOD} from './calculators.mjs';
import {houseMap,zoneTrace,traceMarkup,lineMap} from './transport-visual.mjs';
import {housePriceResult,defaultShares} from './transport-price.mjs';
import {priceControls,priceSummary,priceBreakdown} from './transport-price-view.mjs';
import {createTallyView} from './tally-view.mjs';
import {createTransportView} from './transport-v2.mjs';
import {projectData,backupPayload,parseBackup,validateProject} from './project-store.mjs';
import {calculatorFieldVisible} from './calculators.mjs';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currency=n=>new Intl.NumberFormat('da-DK',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const KEY='akkordklar-v1';
const fresh=()=>({schema:1,active:'transport',sub:{},transport:{mode:'house',config:{length:20,depth:12,entry:10,ground:8,crane:0,craneDirection:'left',route:'both',stage:'ground',method:'manual',source:'truck',special:false,excluded:false},agreed:false,amounts:{},pricing:{mode:'uniform',montage:'',withoutT:0,shares:{}},selected:1,pricesReset:false,manual:[{id:uid(),name:'Felt 1',ground:25,crane:0,craneDirection:'left',source:'truck',scaffold:0,base:'',method:'manual',stage:'ground'}]},calcs:{},ledger:[],jobName:'',jobNotes:''});
let state=fresh(),storageAvailable=true,installPrompt=null,toastTimer=null,houseResult=null,genericResult=null;
try{const saved=localStorage.getItem(KEY);if(saved){const v=JSON.parse(saved);if(v.schema===1&&Array.isArray(v.ledger)&&v.transport&&v.calcs){state={...state,...v};if(!GROUPS.some(g=>g.id===state.active))state.active='transport';}}}catch{storageAvailable=false;}
state.transport.config={crane:0,craneDirection:'left',source:'truck',...state.transport.config};
state.transport.pricing={mode:Object.values(state.transport.amounts||{}).some(v=>Number(v)>0)?'zones':'uniform',montage:'',withoutT:0,shares:{},...state.transport.pricing};
state.transport.manual=state.transport.manual.map(row=>({crane:0,craneDirection:'left',source:'truck',...row}));
const SOURCE_STATUS='2026-priser (+2,7 %) er vejledende; den aftalte 2025-priskurant er det formelle grundlag ved fagretlig behandling (forord s. 3).';
const DEADLINE_NOTE='Kritikfrist: 3 arbejdsdage efter bevislig modtagelse / digital overførsel. Modtagelses-/overførselsdagen tæller ikke med. Følg op på digital kritik i indberetningssystemet (Almindelige bestemmelser s. 8–10).';
state.projects??=[];
state.projectId??=uid();
let isProjectSwitch=false;
function persist(){try{if(!isProjectSwitch){const snapshot={id:state.projectId,name:state.jobName||'Unavngivet opgave',updated:new Date().toISOString(),data:projectData(state)};const i=state.projects.findIndex(p=>p.id===state.projectId);if(i<0)state.projects.push(snapshot);else state.projects[i]=snapshot;}localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;}}
const tallyView=createTallyView({getState:()=>state,persist,addLine,toast,advanced:()=>{state.transport.entry='advanced';renderTransport();persist();}});
const transportView=createTransportView({getState:()=>state,persist,addLine,toast,legacy:()=>{state.transport.legacyMode=true;state.transport.mode='manual';renderTransport();persist();}});
function applyTheme(){state.theme??=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.documentElement.dataset.theme=state.theme;const b=document.querySelector('[data-action="theme"]');if(b){b.textContent=state.theme==='dark'?'☀':'☾';b.setAttribute('aria-label',state.theme==='dark'?'Skift til lys visning':'Skift til mørk visning');}}
function projectToolbar(){return `<section class="panel project-toolbar"><label class="field"><span>Mine projekter</span><select data-project-select aria-label="Vælg projekt">${state.projects.map(p=>`<option value="${escape(p.id)}" ${p.id===state.projectId?'selected':''}>${escape(p.id===state.projectId?(state.jobName||p.name):p.name)}</option>`).join('')}</select></label><button class="btn secondary" data-action="new-project">+ Nyt projekt</button><button class="btn secondary" data-action="copy-project">Duplikér projekt</button></section>`;}
function switchProject(id){const selected=state.projects.find(p=>p.id===id);if(!selected||id===state.projectId)return;persist();isProjectSwitch=true;state={...fresh(),...structuredClone(selected.data),projects:state.projects,theme:state.theme,projectId:id,active:'overview'};isProjectSwitch=false;render();toast('Projektet er åbnet.');}
function newProject(){persist();const kept={projects:state.projects,theme:state.theme};state={...fresh(),...kept,projectId:uid(),active:'overview'};render();toast('Nyt projekt oprettet.');}
function copyProject(){persist();state.projectId=uid();state.jobName=`${state.jobName||'Opgave'} · kopi`;render();toast('Projektet er kopieret med alle indtastninger.');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function icon(name){const shapes={truck:'<path d="M3 7h11v10H3zM14 11h4l3 4v2h-7M6 17a2 2 0 1 0 0 .01M18 17a2 2 0 1 0 0 .01"/>',height:'<path d="M5 20V4m-2 2 2-2 2 2M3 18l2 2 2-2M11 20h9V8h-9zM11 12h9M11 16h9M15 8V4"/>',roof:'<path d="m2 12 10-8 10 8M5 10v10h14V10M9 20v-6h6v6"/>',plus:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M12 8v8M8 12h8"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h9a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h9"/>',arrows:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',pen:'<path d="m15 3 5 5-11 11-6 2 2-6zM12 6l5 5M4 20l1-5 4 4"/>',sheet:'<path d="M6 3h9l4 4v14H6zM15 3v5h4M9 12h7M9 16h7"/>',book:'<path d="M12 5v15M3 4c3-1 6-1 9 1 3-2 6-2 9-1v14c-3-1-6-1-9 1-3-2-6-2-9-1z"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||shapes.plus}</svg>`;}
function nav(){const count=state.ledger.length;$('#desktop-nav').innerHTML=GROUPS.map(g=>`<button class="nav-item ${state.active===g.id?'active':''}" data-tab="${g.id}" aria-current="${state.active===g.id?'page':'false'}">${icon(g.icon)}<span>${g.label}</span>${g.id==='overview'&&count?`<span class="nav-count">${count}</span>`:''}</button>`).join('');$('#mobile-nav').innerHTML=GROUPS.map(g=>`<button class="mobile-tab ${state.active===g.id?'active':''}" data-tab="${g.id}" aria-current="${state.active===g.id?'page':'false'}">${g.short}${g.id==='overview'&&count?` (${count})`:''}</button>`).join('');}
const titles={transport:['Din akkordseddel.<br><em>Fra grej til beløb.</em>','1. Optæl → 2. Transport → 3. Resultat.'],height:['Højt op.<br><em>Rigtigt afregnet.</em>','Find tillægget til delene i den rigtige monteringshøjde.'],roof:['Tag på.<br><em>Styr på tillægget.</em>','Skråt tag, telt eller klimaskærm. Vælg den regel, der passer.'],extras:['Det ekstra arbejde.<br><em>Det rette tillæg.</em>','Omlæsning og eftermontage har hver deres grundlag.'],travel:['Kilometerne tæller.<br><em>Efter de første 20.</em>','Beregn kørselsbetalingen pr. mand og arbejdsdag.'],movement:['Flyt det.<br><em>Regn det rigtigt.</em>','Arbejdsdæk, montagedæk, nedtagning og grundpriser.'],agreements:['Særlig opgave.<br><em>Tydelig aftale.</em>','Gem den aftalte afregning og det regnestykke, der hører til.'],overview:['Dine beregninger.<br><em>Samlet ét sted.</em>','Et læsbart grundlag til din egen kontrol og akkordseddel.'],guide:['Forstå reglen.<br><em>Følg regnestykket.</em>','Korte forklaringer og direkte henvisninger til priskuranten.']};
function render(){nav();const g=GROUPS.find(g=>g.id===state.active)||GROUPS[0],i=GROUPS.indexOf(g);$('#page-title').innerHTML=titles[g.id][0];$('#page-description').textContent=titles[g.id][1];$('#page-eyebrow').textContent=`${String(i+1).padStart(2,'0')} / ${g.short.toUpperCase()}`;$('#breadcrumb-name').textContent=g.label;document.title=`${g.short} · Akkordklar`;if(g.id==='transport')renderTransport();else if(g.id==='overview')renderOverview();else if(g.id==='guide')renderGuide();else renderCalcGroup(g.id);persist();}
function switchTab(id){if(!GROUPS.some(g=>g.id===id))return;state.active=id;history.replaceState(null,'',`#${id}`);render();window.scrollTo({top:0,behavior:'instant'});$('#mobile-nav .active')?.scrollIntoView({inline:'center',block:'nearest'});}
function field(id,label,value,unit='m',hint='',attrs=''){return `<label class="field"><span>${label}</span><span class="input-wrap"><input type="number" inputmode="decimal" min="0" step="0.01" value="${escape(value)}" aria-label="${escape(label)}" ${attrs}><span>${unit}</span></span>${hint?`<small>${hint}</small>`:''}</label>`;}
function check(label,value,attrs='',hint=''){return `<label class="check"><input type="checkbox" ${value?'checked':''} ${attrs}><span>${label}${hint?`<small>${hint}</small>`:''}</span></label>`;}
function transportControls(){
 const c=state.transport.config;
 return `<div class="controls">
 <section class="panel control-panel"><h2 class="step-heading"><span class="step-circle">1</span> Hvor flytter I grejet?</h2><div class="choice-stack"><button class="choice ${c.stage==='ground'?'active':''}" data-stage="ground">Rundt på jorden<small>Grejet frem til flere hejsesteder rundt om huset.</small></button><button class="choice ${c.stage==='scaffold'?'active':''}" data-stage="scaffold">På stilladset<small>Grejet til ét hejs, derefter videre på stilladset.</small></button></div></section>
 <section class="panel control-panel"><h2 class="step-heading"><span class="step-circle">2</span> Bil → materialer → hejs</h2>
 <label class="field"><span>Hvem afsætter materialerne?</span><select data-h-field="source"><option value="truck" ${c.source==='truck'?'selected':''}>Stilladsbilens kran / fra bilen</option><option value="external" ${c.source==='external'?'selected':''}>Fremmed vognmand</option></select></label>
 <div class="field-grid">${field('crane','Kran fra bil til materialer',c.crane,'m','Sæt 0, hvis der ikke kranes.',`data-h-field="crane"`)}<label class="field"><span>Kranretning på skitsen</span><select data-h-field="craneDirection"><option value="left" ${c.craneDirection==='left'?'selected':''}>Til venstre</option><option value="right" ${c.craneDirection==='right'?'selected':''}>Til højre</option></select></label></div>
 ${field('ground',c.stage==='ground'?'Videre fra materialer til adgang':'Videre fra materialer til hejs',c.ground,'m','Kun strækket efter afsætning. Kranens meter lægges til særskilt.',`data-h-field="ground"`)}
 <p class="hint">Stilladsbilens kran ved aflæsning tæller med, som i figur C2. Ved fremmed vognmand starter T-målet ved afsætningen; kranleddet vises, men lægges ikke til.</p>
 </section>
 <section class="panel control-panel"><h2 class="step-heading"><span class="step-circle">3</span> Mål vejen rundt om huset</h2><div class="field-grid">${field('length','Forside & bagside',c.length,'m','',`data-h-field="length"`)}${field('depth','De to gavle',c.depth,'m','',`data-h-field="depth"`)}${field('entry','Adgang fra venstre',c.entry,'m','Mål fra venstre hjørne på forsiden.',`data-h-field="entry"`)}</div>
 <p class="hint">Mål langs transportlinjen omkring hjørnerne. Kranleddet og strækket frem til adgangen skal ikke også lægges ind i disse mål.</p>
 <div class="route-options">${[['both','Begge veje','↔'],['cw','Kun via højre','↱'],['ccw','Kun via venstre','↰']].map(([v,t,a])=>`<button data-route="${v}" class="${c.route===v?'active':''}"><span>${t}</span><b>${a}</b></button>`).join('')}</div>
 <p class="hint">Højre/venstre ses fra vejen. Ved én vej er den anden adgang lukket ved starten. Ved andre barrierer: brug Egne afstande.</p>
 <label class="field" style="margin-top:16px"><span>Transportmiddel på jorden</span><select data-h-field="method"><option value="manual" ${c.method==='manual'?'selected':''}>Håndkraft uden hjul</option><option value="wheels" ${c.method==='wheels'?'selected':''}>Manuelt med hjul</option></select><small>Samme trintabel i beregneren: +7 procentpoint pr. påbegyndt 20 m efter 55 m.</small></label>
 ${check('Transportveje og metode er afklaret med virksomheden',state.transport.agreed,'data-h-agreed','Hvidbog A6: flere mulige transportveje afklares før opgaven. Modellen bruger den korteste åbne vej ved adgang begge veje.')}
 <details class="details-control"><summary>Undtagelser & regelgrundlag</summary><div class="detail-content"><div class="checks">${check('Særlige forhold efter A8',c.special,'data-h-field="special"','Ekstraordinære transportforhold, der skal akkorderes særskilt.')}${check('Kun en flytning uden ret til T',c.excluded,'data-h-field="excluded"','Fx flytning efter A12.')}</div><p class="hint">Beregningsmodellen følger trintabellen i pkt. 27, også uden hjul. A6 nævner hjul i teksten om transport over 55 m; den formulering er bevaret i kilderne og bruges ikke som stopklods her. Kran til montage af telt er omfattet af A18, ikke C2-aflæsningen.</p></div></details>
 </section></div>`;
}
function renderTransport(){if(state.transport.entry!=='advanced'){tallyView.mount();return;}if(!state.transport.legacyMode){transportView.mount();return;}const mode=state.transport.mode;$('#view-panel').innerHTML=`<div class="tk-actions"><button class="btn secondary" data-action="new-flow">← Til transportens fire trin</button></div><div class="modebar"><div class="segmented" aria-label="Beregningsmodel"><button data-mode="house" class="${mode==='house'?'active':''}">Rundt om huset</button><button data-mode="manual" class="${mode==='manual'?'active':''}">Egne afstande</button></div><button class="link-button example-button" data-action="example-c2">Vis figur C2 ↗</button></div>${mode==='house'?`${priceControls(state.transport.pricing,safeZones())}<div class="transport-layout">${transportControls()}<div id="house-live" class="map-column"></div></div><div id="house-table"></div>`:manualShell()}`;if(mode==='house')updateHouse(false);else updateManual();}

function color(p){if(p===null)return '#9c8b78';const palette=['#4d8d7c','#709b5d','#baa343','#ce7c3f','#b9543a','#964844','#754b55','#534757'];return palette[Math.min(Math.max(Math.round(p/7)-1,0),palette.length-1)];}
function ratePill(p){const c=color(p);return `<span class="rate-pill" style="background:${c}16;color:${c}">${p===null?'Afklares':`${fmt(p)} %`}</span>`;}
function model(){return houseZones(state.transport.config);}
function safeZones(){try{return model().zones;}catch{return [];}}
function houseValues(result){return housePriceResult(result.zones,state.transport.pricing,state.transport.amounts);}
function mapMarkup(result){const z=result.zones.find(z=>z.index===state.transport.selected)||result.zones[0];return houseMap(state.transport.config,result,z);}
function updateHouse(keepTable=false){
 let result;try{result=model();houseResult=result;}catch(e){houseResult=null;$('#house-live').innerHTML=`<div class="error-message">${escape(e.message)}</div>`;$('#house-table').innerHTML='';return;}
 const t=state.transport,c=t.config,z=result.zones.find(z=>z.index===t.selected)||result.zones[0];t.selected=z.index;
 const rates=[...new Set(result.zones.filter(z=>z.valid).map(z=>z.percent))].sort((a,b)=>a-b),values=houseValues(result),trace=zoneTrace(c,z);
 $('#house-live').innerHTML=`<section class="panel map-panel"><div class="panel-header"><h2>Følg grejets vej</h2><span class="micro-tag">BIL → MATERIALER → HEJS</span></div><div class="map-topline"><span>Transportlinje <strong>${fmt(result.perimeter)} m</strong></span><span>Adgang <strong>${c.route==='both'?'begge veje':c.route==='cw'?'via højre':'via venstre'}</strong></span></div><div class="map-wrap">${mapMarkup(result)}</div><div class="map-legend">${rates.map(p=>`<span class="legend-item"><i style="background:${color(p)}"></i>${fmt(p)} %</span>`).join('')}${!result.valid?'<span class="legend-item"><i style="background:#9c8b78"></i>Afklares</span>':''}<span class="legend-extra">Tryk på en zone</span></div><div class="route-key"><span><i class="crane-line"></i>Kran</span><span><i class="carry-line"></i>Videre på jorden</span><span><i class="selected-line"></i>Valgt rute</span></div><div class="selected-zone"><div><strong>Zone ${z.index} · ${z.side}</strong><small>${fmt(z.from)}–${fmt(z.to)} m langs siden.<br>${c.stage==='ground'?`${fmt(z.groundMin)}–${fmt(z.groundMax)} m samlet til hejs, inkl. det kranled der tæller med.`:`${fmt(result.groundTotal)} m til hejs, derefter ${fmt(z.distanceMin)}–${fmt(z.distanceMax)} m på stilladset.`}</small></div><div class="zone-rate">${z.percent===null?'?':`${fmt(z.percent)} %`}<small>FOR GREJET HER</small></div></div>${traceMarkup(trace,{sample:true})}</section>
 <div class="result-strip"><div class="stat"><span>LAVESTE ZONE</span><strong>${rates.length?`${fmt(rates[0])} %`:'—'}</strong><small>Kun for grejet i den zone</small></div><div class="stat"><span>HØJESTE ZONE</span><strong>${result.valid&&rates.length?`${fmt(rates.at(-1))} %`:'Afklares'}</strong><small>${result.valid?'De fjerneste zoner':'Der er særlige forhold'}</small></div><div class="stat accent"><span>TILLÆG I KRONER</span><strong>${values.complete?currency(values.amount):'—'}</strong><small>${values.complete?`${fmt(values.percent)} % vægtet`:'Skriv montageprisen ovenfor'}</small></div></div>
 ${!result.valid?`<div class="note-card warning"><span class="note-symbol">!</span><div>${escape(result.zones.find(z=>!z.valid)?.reason||'Kontrollér forholdene.')}</div></div>`:`<div class="note-card"><span class="note-symbol">↳</span><div><b>Hvert stræk tæller én gang.</b><br>${c.stage==='ground'?'Kranled + videre til adgang + ruten på jorden frem til hver zones hejs.':'Kranled + videre til hejs giver første sats. Transporten på stilladset giver eventuelle ekstra trin.'}</div></div>`}
 ${c.source==='external'?'<div class="note-card neutral"><div>Fremmed vognmand: kranleddet vises uden for T-målet. A6 starter målingen ved afsætningsstedet og beskriver særskilt afregning af indhejsning på forbrugt tid. Se A18 for teltmontage.</div></div>':''}`;
 if(!keepTable)$('#house-table').innerHTML=houseTable(result,values);updateHouseTotal(result,values);
}

function legacyHouseTable(result,values){const t=state.transport,c=t.config;return `<section class="panel zone-section"><div class="section-head"><div><h2>Fra zoner til dit samlede tillæg</h2><p>Indtast de <b>fulde T-berettigede grundpriser</b> for grejet i hver zone. Skriv 0, hvis der ikke er grej i zonen. Procenten skal vægtes efter kroner, ikke efter meter.</p></div><span class="micro-tag">A6 · PKT. 27</span></div>${t.pricesReset?'<div class="period-note">Ruten er ændret. Tidligere zonebeløb er nulstillet, så beløb fra den gamle opdeling ikke blandes med den nye.</div>':''}<div class="table-scroll"><table class="zone-table"><thead><tr><th>Zone & placering</th><th>${c.stage==='ground'?'Bil / afsætning → hejs':'Hejs → montage'}</th><th>Tillæg</th><th class="text-right">T-grundlag, kr.</th><th class="text-right">Tillæg, kr.</th></tr></thead><tbody>${result.zones.map(z=>`<tr class="${z.index===t.selected?'selected':''}" data-zone-row="${z.index}"><td><button class="link-button zone-name" data-zone="${z.index}"><span class="zone-num">${z.index}</span><span>${z.side}<small>${fmt(z.from)}–${fmt(z.to)} m langs siden</small></span></button></td><td class="table-numeric" data-label="${c.stage==='scaffold'?'Fra hejs på stilladset':c.source==='external'?'Fra afsætning til hejs':'Til hejs, inkl. kran'}">${fmt(c.stage==='ground'?z.groundMin:z.distanceMin)}–${fmt(c.stage==='ground'?z.groundMax:z.distanceMax)} m</td><td data-label="Tillæg">${ratePill(z.percent)}</td><td class="text-right" data-label="T-grundlag, kr."><input class="table-input" type="number" inputmode="decimal" min="0" step="0.01" data-zone-base="${z.id}" value="${escape(t.amounts[z.id]??'')}" placeholder="0,00" aria-label="T-grundlag i kroner for zone ${z.index}"></td><td class="text-right table-numeric" data-label="Tillæg, kr."><span data-zone-money="${z.id}">${zoneMoney(z,t.amounts[z.id])}</span></td></tr>`).join('')}</tbody></table></div><p class="hint">Til hejs: præcis 25 m er 7 %, og 25,01 m er 14 %. På stilladset beregnes de ekstra trin fra hejs ud over den relevante 10 eller 15 m-grænse. Delene fordeles efter deres faktiske placering. Diagrammets længder er en model; delene tælles i zonerne.</p><div id="house-aggregate"></div><details class="estimate-box"><summary>Se et overslag, hvis samme T-grundpris ligger pr. meter</summary><div class="estimate-result">${uniformEstimate(result.zones)!==null?`<strong>${fmt(uniformEstimate(result.zones))} %</strong> ved ens T-grundpris pr. meter langs hele transportlinjen.`:'Overslaget kan ikke beregnes, før alle stræk har en afklaret sats.'}<br>Det er et længdevægtet overslag. Flere dæk, højere stillads eller forskellige materialer ændrer fordelingen. Overslaget bruges ikke som dit faktiske krav.</div></details><div class="source-link"><a href="${SOURCE_URL}#page=17" target="_blank" rel="noopener">Priskuranten A6–A8 / pkt. 27, s. 17–18 og 40 ↗</a> · <a href="https://www.danskindustri.dk/DownloadDocument?docid=222595&id=580131#page=16" target="_blank" rel="noopener">Hvidbog A6 om valg af transportvej ↗</a></div></section>`;}
function zoneMoney(z,val){if(val===''||val===undefined||val===null)return '—';const v=Number(String(val).replace(',','.'));return Number.isFinite(v)&&v>=0&&z.valid?currency(Math.round(v*100*z.percent/100)/100):'—';}
function houseTable(result,values){
 if(state.transport.pricing.mode==='zones')return legacyHouseTable(result,values);
 const c=state.transport.config;
 return `<section class="panel zone-section montage-total-panel"><div class="section-head"><div><h2>Montagepris med transport</h2><p>Montageprisen plus det beregnede transporttillæg. Længere transport får sin højere sats med i regnestykket.</p></div><span class="micro-tag">A6 · PKT. 27</span></div><div id="house-aggregate"></div><div id="house-price-breakdown"></div><details class="details-control"><summary>Se de ${result.zones.length} afstandszoner i modellen</summary><div class="detail-content"><p class="hint">Zonerne er beregnet automatisk. Du behøver ikke indtaste et beløb i dem.</p><div class="zone-readout">${result.zones.map(z=>`<button data-zone="${z.index}" class="zone-readout-row"><span>${z.side}<small>${fmt(z.from)}–${fmt(z.to)} m langs siden</small></span><span>${fmt(c.stage==='ground'?z.groundMin:z.distanceMin)}–${fmt(c.stage==='ground'?z.groundMax:z.distanceMax)} m</span>${ratePill(z.percent)}</button>`).join('')}</div></div></details><div class="source-link"><a href="${SOURCE_URL}#page=17" target="_blank" rel="noopener">A6–A8 og pkt. 27 ↗</a></div></section>`;
}
function updateHouseTotal(result,values=houseValues(result)){
 const target=$('#house-aggregate');if(!target)return;
 target.innerHTML=priceSummary(values,state.transport.agreed,{excluded:state.transport.config.excluded});
 const breakdown=$('#house-price-breakdown');if(breakdown)breakdown.innerHTML=priceBreakdown(values);
 for(const z of result.zones){const el=$(`[data-zone-money="${z.id}"]`);if(el)el.textContent=zoneMoney(z,state.transport.amounts[z.id]);}
 for(const el of $$('[data-side-price]')){const sideBase=values.rows?.filter(z=>z.side===el.dataset.sidePrice).reduce((n,z)=>n+Number(z.base||0),0);el.textContent=values.complete?currency(sideBase):'—';}
}
function manualShell(){return `<div class="note-card neutral" style="margin-bottom:18px"><span class="note-symbol">↳</span><div><b>Ét forløb pr. gruppe grej.</b><br>Indtast kranleddet og den efterfølgende transport hver for sig. Den samlede afstand til hejs beregnes automatisk. Ved flere hejsesteder eller afstandsgrupper: opret flere linjer.</div></div><section class="panel zone-section" style="margin-top:0"><div class="section-head"><div><h2>Dine transportlinjer</h2><p>Samme materielgrundlag følger hele forløbet. Kran og bæring udløser ikke hver sit opstartstillæg.</p></div><button class="btn secondary small" data-action="add-manual">+ Ny linje</button></div><div id="manual-lines">${state.transport.manual.map(manualRow).join('')}</div><div id="manual-total"></div><div class="source-link"><a href="${SOURCE_URL}#page=53" target="_blank" rel="noopener">Figur C2 ↗</a> · <a href="${SOURCE_URL}#page=40" target="_blank" rel="noopener">Trintabellen i pkt. 27 ↗</a><br>Kran ved aflæsning fra stilladsbilen medregnes i C2-forløbet. Fremmed vognmands indhejsning starter et nyt målepunkt ved afsætningen. Særlige forhold efter A8 og teltmontage efter A18 opgøres efter deres egne regler.</div></section>`;}
function manualRow(row,i){return `<div class="panel manual-card" data-manual-card="${escape(row.id)}"><div class="section-head"><label class="field" style="margin:0;flex:1"><span>Grej / placering</span><input type="text" value="${escape(row.name)}" data-manual-id="${escape(row.id)}" data-manual-field="name" maxlength="120" aria-label="Navn på transportlinje ${i+1}"></label><button class="icon-button" data-remove-manual="${escape(row.id)}" aria-label="Fjern transportlinje ${i+1}">×</button></div><div class="field-grid">
 <label class="field"><span>Hvem afsætter materialerne?</span><select data-manual-id="${escape(row.id)}" data-manual-field="source">${[['truck','Stilladsbilen / egen kranaflæsning'],['external','Fremmed vognmand']].map(([v,l])=>`<option value="${v}" ${row.source===v?'selected':''}>${l}</option>`).join('')}</select></label>
 <label class="field"><span>Transportmiddel efter afsætning</span><select data-manual-id="${escape(row.id)}" data-manual-field="method">${[['manual','Håndkraft uden hjul'],['wheels','Manuelt med hjul'],['truck','Truck / teleskoplæsser']].map(([v,l])=>`<option value="${v}" ${row.method===v?'selected':''}>${l}</option>`).join('')}</select></label>
 ${field('crane','Kran fra bil til materialer',row.crane,'m','0, hvis der ikke kranes.',`data-manual-id="${escape(row.id)}" data-manual-field="crane"`)}
 <label class="field"><span>Kranretning på skitsen</span><select data-manual-id="${escape(row.id)}" data-manual-field="craneDirection"><option value="left" ${row.craneDirection==='left'?'selected':''}>Til venstre</option><option value="right" ${row.craneDirection==='right'?'selected':''}>Til højre</option></select></label>
 ${field('ground','Videre fra materialer til hejs',row.ground,'m','Kun strækket efter afsætning. Kranens meter står i sit eget felt.',`data-manual-id="${escape(row.id)}" data-manual-field="ground"`)}
 <label class="field"><span>Forløb efter hejs</span><select data-manual-id="${escape(row.id)}" data-manual-field="stage"><option value="ground" ${row.stage==='ground'?'selected':''}>Ingen yderligere stilladstransport</option><option value="scaffold" ${row.stage==='scaffold'?'selected':''}>Videre på stilladset</option></select></label>
 ${field('scaffold','Hejs til montage på stilladset',row.scaffold,'m','Den vandrette vej fra hejs til de relevante dele.',`data-manual-id="${escape(row.id)}" data-manual-field="scaffold" ${row.stage==='ground'?'disabled':''}`)}
 ${field('base','Fuldt T-grundlag',row.base,'kr.','De transportberettigede grundpriser for denne gruppe grej.',`data-manual-id="${escape(row.id)}" data-manual-field="base"`)}
 </div><div class="manual-result" data-manual-result="${escape(row.id)}"></div><div data-manual-visual="${escape(row.id)}"></div><div class="hint" data-manual-explanation="${escape(row.id)}"></div></div>`;}
function updateManual(){const rows=[];for(const row of state.transport.manual){let r;try{r=calculateTransport(row);}catch(e){r={valid:false,reason:e.message,percent:null};}rows.push({...r,base:row.base});$(`[data-manual-result="${escape(row.id)}"]`).innerHTML=r.valid?`<span>Samlet transporttillæg</span>${ratePill(r.percent)}<strong>${zoneMoney(r,row.base)} kr.</strong>`:'<span class="rate-pill" style="background:#fbefdd;color:#906527">Afklares</span>';$(`[data-manual-visual="${escape(row.id)}"]`).innerHTML=r.valid?lineMap(row,r)+traceMarkup(r):'';$(`[data-manual-explanation="${escape(row.id)}"]`).textContent=r.valid?'T beregnes på det relevante fulde grundlag, også ved nedtagning.':'';$(`[data-manual-id="${escape(row.id)}"][data-manual-field="scaffold"]`).disabled=row.stage==='ground';if(!r.valid)$(`[data-manual-explanation="${escape(row.id)}"]`).textContent=r.reason;}
 const total=weightedResult(rows);$('#manual-total').innerHTML=`<div class="table-footer"><div class="aggregate">${total.complete?`Samlet transporttillæg <strong>${currency(total.amount)} kr.</strong><small>${fmt(total.percent)} % af ${currency(total.base)} kr. i fuldt T-grundlag.</small>`:'<b>Udfyld T-grundlag for alle linjer.</b><small>Procenterne er vist ovenfor. Kronebeløb kræver grundpriser; skriv 0 ved en tom materielgruppe.</small>'}</div><button class="btn" data-action="save-manual" ${total.complete?'':'disabled'}>Føj til mit ark ↗</button></div>`;
}

function inputVisible(calc,f,v){return calculatorFieldVisible(calc,f,v);}
function genericField(calc,f,v){const at=`data-calc="${calc.id}" data-calc-field="${f.id}"`;const outer=`data-generic-field="${f.id}" ${inputVisible(calc,f,v)?'':'hidden'}`;if(f.type==='checkbox')return `<div ${outer}>${check(escape(f.label),v[f.id],at,escape(f.hint))}</div>`;if(f.type==='select')return `<label class="field" ${outer}><span>${escape(f.label)}</span><select ${at}>${f.options.map(([value,label])=>`<option value="${escape(value)}" ${v[f.id]===value?'selected':''}>${escape(label)}</option>`).join('')}</select>${f.hint?`<small>${escape(f.hint)}</small>`:''}</label>`;if(f.type==='text')return `<label class="field" ${outer}><span>${escape(f.label)}</span><textarea maxlength="1500" ${at}>${escape(v[f.id])}</textarea>${f.hint?`<small>${escape(f.hint)}</small>`:''}</label>`;return `<div ${outer}>${field(f.id,escape(f.label),v[f.id],escape(f.unit),escape(f.hint),`${at} step="${f.step||'0.01'}"`)}</div>`;}
function calcValues(calc){state.calcs[calc.id]={...defaults(calc),...state.calcs[calc.id]};return state.calcs[calc.id];}
function renderCalcGroup(group){const calcs=CALCULATORS.filter(c=>c.group===group);let selected=state.sub[group];if(!calcs.some(c=>c.id===selected))selected=calcs[0].id;state.sub[group]=selected;const calc=calcs.find(c=>c.id===selected),v=calcValues(calc);$('#view-panel').innerHTML=`<div class="subtabs" aria-label="Beregnere i denne fane">${calcs.map(c=>`<button class="subtab ${c.id===selected?'active':''}" data-sub="${c.id}">${escape(c.title)}</button>`).join('')}</div><div class="calc-layout"><section class="panel calc-panel"><div class="section-head"><div><h2>${escape(calc.title)}</h2><div class="rule-ref">${escape(calc.ref)}</div></div><span class="micro-tag">${escape(calc.tag)}</span></div><p class="calc-intro">${escape(calc.intro)}</p><div class="calc-fields">${calc.fields.map(f=>genericField(calc,f,v)).join('')}</div></section><div class="calc-result-col"><div><div id="calc-result"></div></div><section class="panel source-panel"><h3>Sådan skal du forstå det</h3>${calc.notes.map(t=>`<p>${escape(t)}</p>`).join('')}<div class="source-link"><a href="${sourceLink(calc.page)}" target="_blank" rel="noopener">Se reglen i priskuranten ↗</a><br>${escape(calc.ref)}</div></section></div></div><p class="rule-ref" style="margin-top:20px">Kronebeløb: ${PERIOD}. Tillæg regnes af deres eget berettigede grundlag — ikke automatisk af andre tillæg.</p>`;updateGeneric(calc);}
function updateGeneric(calc){const v=calcValues(calc);for(const f of calc.fields){const el=$(`[data-generic-field="${f.id}"]`);if(el)el.hidden=!inputVisible(calc,f,v);}const r=runCalculator(calc.id,v);genericResult=r;$('#calc-result').innerHTML=`<section class="panel result-panel"><div class="result-kicker">${r.kind?escape(r.kind):'DIT TILLÆG'} · ${escape(calc.tag)}</div>${r.valid?`<div class="result-total">${currency(r.amount)}<small>kr.</small></div>${r.percent!==null&&r.percent!==undefined?`<div class="result-percent">${fmt(r.percent)} % af det valgte grundlag</div>`:''}${r.distribution?`<div class="distribution-table"><table><thead><tr><th>Montør</th><th>Vægtede timer</th><th>Beløb</th></tr></thead><tbody>${r.distribution.map(m=>`<tr><td>${escape(m.name)}</td><td>${fmt(m.weightedHours)}</td><td>${currency(m.amount)} kr.</td></tr>`).join('')}</tbody></table></div>`:''}<div class="result-formula">${escape(r.formula)}</div><p class="result-explanation">${escape(r.explanation)}</p>${r.noAdd?'<span class="rule-ref" style="color:#b9cbbd">En kontrol / fordeling, som ikke lægges oven i dit ark.</span>':`<button class="btn full-width" data-action="save-calc" data-calc-id="${calc.id}">Føj til mit beregningsark <span>↗</span></button>`}`:`<div class="invalid">${escape(r.reason)}</div><div class="result-explanation">Ret eller afklar forudsætningen. Der gemmes ingen ubekræftet standardsats.</div>`}</section>`;}

function addLine(line){state.ledger.push({id:uid(),created:new Date().toISOString(),period:PERIOD,annotation:'',...line});persist();nav();toast('Beregningen er føjet til Mit ark.');}
function saveHouse(){const r=model(),t=state.transport,total=houseValues(r);if(!total.complete||!t.agreed||total.provisional)return;const c=t.config;
 const distribution=total.mode==='uniform'?'Forudsætter samme montagepris pr. meter langs hele transportlinjen; automatisk fordeling efter længde.':total.mode==='sides'?'Fordelt efter brugerens prisandele på siderne, med ens montagepris pr. meter inden for hver side.':'Faktiske fulde T-grundpriser opgjort pr. zone.';
 addLine({title:'Transport rundt om huset',kind:'tillæg',amount:total.amount,percent:total.percent,formula:`Montagepris ${currency(total.montage)} kr.${total.withoutT>0?` minus ${currency(total.withoutT)} kr. uden ret til T`:''} Transportgrundlag ${currency(total.base)} kr. × vægtet sats ${fmt(total.percent)} % = ${currency(total.amount)} kr. Procenten er vist afrundet; tillægget er beregnet fra de enkelte delbeløb. Montagepris inkl. transport: ${currency(total.montageWithTransport)} kr. Kun 7 % ville være ${currency(total.sevenAmount)} kr.; forskel ${currency(total.difference)} kr.`,explanation:`${distribution} ${fmt(Number(c.length))} × ${fmt(Number(c.depth))} m transportlinje. ${c.stage==='ground'?'Transport på jorden':'Til ét hejs og videre på stilladset'}. ${c.route==='both'?'Korteste af to åbne ruter':c.route==='cw'?'Kun via højre':'Kun via venstre'}. Kran ${fmt(Number(c.crane))} m; videre fra materialer ${fmt(Number(c.ground))} m. ${c.source==='external'?'Kranstræk uden for T-målet.':'Kran ved aflæsning med i T-målet.'} ${c.method==='wheels'?'Med hjul':'Håndkraft uden hjul'}. Ruter/metode markeret afklaret.`,source:'A6–A8 / pkt. 27 · s. 17–18, 40 · Hvidbog A6',inputs:{...structuredClone(c),pricing:structuredClone(t.pricing)},zones:total.rows.map(z=>({side:z.side,from:z.from,to:z.to,percent:z.percent,base:Number(z.base),groundMin:z.groundMin,groundMax:z.groundMax,distanceMin:z.distanceMin,distanceMax:z.distanceMax})),snapshotVersion:RULE_VERSION});}
function saveManual(){const arr=state.transport.manual.map(row=>({...calculateTransport(row),base:row.base})),total=weightedResult(arr);if(!total.complete||arr.some(r=>r.provisional))return;addLine({title:'Transport efter egne afstande',kind:'tillæg',amount:total.amount,percent:total.percent,formula:`Σ (linjens fulde T-grundlag × linjens sats) = ${currency(total.amount)} kr. Vægtet sats ${fmt(total.percent)} %.`,explanation:state.transport.manual.map((row,i)=>`${row.name}: ${row.crane} m kran (${row.source==='external'?'uden for T-målet':'med i T-målet'}) + ${row.ground} m videre = ${arr[i].groundTotal} m til hejs${row.stage==='scaffold'?` + ${row.scaffold} m på stillads`:''}, ${row.method}, ${arr[i].percent} % af ${row.base} kr.`).join(' | '),source:'A6–A8 / pkt. 27 · s. 17–18, 40',inputs:structuredClone(state.transport.manual),snapshotVersion:RULE_VERSION});}
function saveCalc(id){const c=CALCULATORS.find(c=>c.id===id),v=calcValues(c),r=runCalculator(id,v);if(!r.valid||r.noAdd)return;addLine({title:c.title,kind:r.kind||'tillæg',amount:r.amount,percent:r.percent,formula:r.formula,explanation:r.explanation,source:c.ref,inputs:structuredClone(v),snapshotVersion:RULE_VERSION});}
function renderOverview(){persist();const lines=state.ledger,totalCents=lines.reduce((n,l)=>n+Math.round(l.amount*100),0);$('#view-panel').innerHTML=`${projectToolbar()}<section class="panel overview-top"><div class="overview-grid"><label class="field"><span>Opgave / adresse</span><input type="text" maxlength="180" data-job="jobName" placeholder="Fx Tagudskiftning, Fanø" value="${escape(state.jobName)}"></label><div class="field"><span>Satser i beregningerne</span><div class="hint">${PERIOD}<br>${lines.length} gemte beregninger</div></div><label class="field field-wide"><span>Noter til opgaven</span><textarea class="overview-notes" maxlength="4000" data-job="jobNotes" placeholder="Fx adgangsforhold, afklaring med virksomheden og dato.">${escape(state.jobNotes)}</textarea></label></div><div class="button-row"><button class="btn" data-action="share">Del tekst ↗</button><button class="btn secondary" data-action="print">${isNative()?'Del udskriftsark':'Udskriv / gem PDF'}</button><button class="btn secondary" data-action="backup">Gem sikkerhedskopi ↓</button><button class="btn secondary" data-action="import">Åbn sikkerhedskopi ↑</button></div></section>${lines.length?`<div class="note-card neutral" style="margin-bottom:18px"><div><b>Arket summerer kun de linjer, du selv vælger.</b><br>Grundpriser, arbejdspriser og særskilte aftaler er mærket hver for sig. Gem ikke samme arbejde både som en samlet arbejdspris og som delpriser.</div></div><section class="panel"><div class="print-title"><h1 style="font-size:26px">Akkordklar · ${escape(state.jobName||'Beregningsark')}</h1><p>${escape(state.jobNotes)}</p><p class="rule-ref">Udskrevet ${new Date().toLocaleDateString('da-DK')} · Satser ${PERIOD}</p></div>${lines.map(l=>`<article class="ledger-row"><div><span class="ledger-label">${escape(l.kind)} ${l.percent!==null&&l.percent!==undefined?`· ${fmt(l.percent)} %`:''}</span><h3>${escape(l.title)}</h3><p>${escape(l.formula)}</p><p>${escape(l.explanation)}</p>${l.zones?`<details><summary>Se de gemte transportzoner</summary><div class="detail-content">${l.zones.map((z,i)=>`<p>Zone ${i+1}: ${escape(z.side)} ${fmt(z.from)}–${fmt(z.to)} m · ${currency(z.base)} kr. × ${fmt(z.percent)} %${z.groundTotal!=null?` · ${fmt(z.groundTotal)} m til hejs`:''}${z.scaffold?` · ${fmt(z.scaffold)} m på stillads`:''}${z.manualDistance?' · manuelt rettet afstand':''}</p>`).join('')}</div></details>`:''}${l.materialRows?.length?`<details><summary>Se materialer og mellemregninger</summary><div class="detail-content">${l.materialRows.map(m=>`<p><b>${escape(m.label)}</b><br>${escape(m.formula)} = ${currency(m.workAmount)} kr. · T-grundlag ${currency(m.tBase)} kr.<br>${escape(m.ref)} · ${escape(m.zoneName||'Uden T')}</p>`).join('')}</div></details>`:''}<p class="rule-ref">${escape(l.source)} · ${escape(l.snapshotVersion||'Tidligere regelversion — kontrollér før brug')}</p>${l.snapshotVersion!==RULE_VERSION?'<p class="tk-warning">Gemt med en tidligere regelversion. Genberegn ved behov; historiske beløb ændres ikke automatisk.</p>':''}<input class="ledger-annotation" type="text" maxlength="500" data-annotation="${escape(l.id)}" placeholder="Tilføj note til denne linje…" aria-label="Note til ${escape(l.title)}" value="${escape(l.annotation||'')}"><p class="ledger-note-print" style="display:none">${escape(l.annotation||'')}</p></div><div class="ledger-right"><div class="ledger-price">${currency(l.amount)} kr.</div><button class="link-button" data-remove-ledger="${escape(l.id)}">Fjern linje</button></div></article>`).join('')}<div class="ledger-total"><div><span>Samlet valgte beløb</span><small>Kun linjerne ovenfor. Ikke automatisk hele akkordsummen.</small></div><strong>${currency(totalCents/100)} kr.</strong></div></section>`:`<section class="panel overview-empty"><div class="empty-mark">▤</div><h2>Dit ark starter med én beregning.</h2><p>Vælg en beregner, ret tallene og tryk “Føj til mit beregningsark”. Regnestykket og forudsætningerne gemmes sammen.</p><button class="btn" data-tab="transport">Start med transport ↗</button></section>`}<p class="rule-note">${SOURCE_STATUS} ${DEADLINE_NOTE}</p><p class="rule-ref" style="margin-top:18px">${storageAvailable?'Gemmes på denne enhed. Brug sikkerhedskopi til at flytte arket til en anden telefon.':'Enheden tillader ikke lokal lagring. Hent en sikkerhedskopi, før du lukker appen.'} Ændringer i beregnerne retter ikke allerede gemte linjer; fjern den gamle og gem den nye, hvis noget skal erstattes.</p>`;}
function reportText(){const lines=state.ledger;return ['AKKORDKLAR · BEREGNINGSARK',state.jobName||'Opgave ikke navngivet',`Satser: ${PERIOD}`,state.jobNotes,'',...lines.flatMap((l,i)=>[`${i+1}. ${l.title} [${l.kind}]`,`${currency(l.amount)} kr.${l.percent!=null?` · ${fmt(l.percent)} %`:''}`,l.formula,l.explanation,...(l.zones||[]).map((z,j)=>`Zone ${j+1}: ${z.side} ${fmt(z.from)}–${fmt(z.to)} m · ${currency(z.base)} kr. × ${fmt(z.percent)} %`),...(l.materialRows||[]).map(m=>`${m.label}: ${m.formula} = ${currency(m.workAmount)} kr.; T-grundlag ${currency(m.tBase)} kr.; ${m.ref}; ${m.zoneName||'Uden T'}`),`Regel: ${l.source}`,`Version: ${l.snapshotVersion||'Tidligere version'}`,l.annotation?`Note: ${l.annotation}`:'','']),`Samlet valgte beløb: ${currency(lines.reduce((n,l)=>n+Math.round(l.amount*100),0)/100)} kr.`,'Beløbet omfatter kun de valgte linjer, ikke automatisk hele akkorden.',SOURCE_STATUS,DEADLINE_NOTE,`Regler: ${SOURCE_URL}`].filter(x=>x!==null&&x!==undefined).join('\n');}
async function download(blob,name){if(isNative()){try{await shareFile(name,await blob.text());}catch(e){if(!/cancel|dismiss/i.test(String(e.message)))toast('Kunne ikke dele filen på denne enhed.');}return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function shareReport(){const text=reportText();try{if(isNative()){await shareText(text);}else if(navigator.share){await navigator.share({title:'Akkordklar · beregningsark',text});}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);toast('Beregningsarket er kopieret som tekst.');}else download(new Blob([text],{type:'text/plain;charset=utf-8'}),'akkordklar-beregningsark.txt');}catch(e){if(e.name!=='AbortError')download(new Blob([text],{type:'text/plain;charset=utf-8'}),'akkordklar-beregningsark.txt');}}
function renderGuide(){const tools=GROUPS.filter(g=>!['overview','guide'].includes(g.id));$('#view-panel').innerHTML=`<div class="period-note"><b>Regelgrundlag og satser:</b> HP3 Provinsen 2025 med 2026-regulering. Kronebeløb er fra din opdaterede PDF for ${PERIOD}. Transportreglerne er sammenholdt med DI’s officielle priskurant og Hvidbog 2025. Appen er et beregningsværktøj; en aftale om særlige forhold skal stå på sit eget grundlag.</div><div class="category-grid">${tools.map(g=>`<button class="category-card" data-tab="${g.id}">${icon(g.icon)}<span><strong>${g.label}</strong><small>${g.desc}</small></span></button>`).join('')}</div><div class="guide-grid"><section class="panel guide-panel"><h2>De tre ting, du skal kende</h2><h3>1. Hvilket grej handler det om?</h3><p>Et tillæg gælder kun det materiel, som opfylder reglen. T betyder transportberettiget, H betyder højdeberettiget. G er grundprisen. Et T-grundlag på 1.000 kr. er summen af grundpriserne for de relevante dele.</p><h3>2. Hvad er det rigtige grundlag?</h3><p>7 % af 1.000 kr. er 70 kr. Hvis en anden regel giver 30 % af de samme 1.000 kr., er det tillæg 300 kr. Der regnes normalt ikke procent af det første tillæg. Forskellige tillæg kan have forskellige materielgrundlag.</p><h3>3. Én montagepris – flere afstande</h3><p>Skriv den samlede montagepris før tillæg. Ved ens opbygning fordeler appen prisen efter længden og beregner én samlet transportprocent af hele beløbet. Grej tæt på bilen kan have 7 %, mens grej længere væk får sin højere sats. Halvdelen af prisen til 7 % og halvdelen til 14 % giver 10,5 % samlet.</p><p>Samme pris pr. meter er en forudsætning, som skal passe til opgaven. Ved mere grej på nogle sider kan du justere de fire prisandele. Der forudsættes stadig ens pris pr. meter inden for hver side. Brug den avancerede fordeling til faktiske zonebeløb ved ujævnt grej på selve siden. De automatiske fordelinger er ikke en optælling af materialerne.</p><div class="note-card"><div>1.000 kr. × 7 % + 3.000 kr. × 28 % = <b>910 kr.</b><br>910 / 4.000 × 100 = <b>22,75 % vægtet tillæg.</b></div></div></section><section class="panel guide-panel"><h2>Transport, helt konkret</h2><div class="table-scroll"><table class="guide-table"><thead><tr><th>Bil / afsætning til hejs</th><th>Tillæg</th></tr></thead><tbody>${[['0–25 m','7 %'],['Over 25–35 m','14 %'],['Over 35–45 m','21 %'],['Over 45–55 m','28 %'],['Over 55–75 m','35 %'],['Over 75–95 m','42 %'],['Derefter','+7 % pr. påbegyndt 20 m']].map(a=>`<tr><td>${a[0]}</td><td>${a[1]}</td></tr>`).join('')}</tbody></table></div><h3>Kranen i figur C2</h3><p>Kran fra stilladsbil til materialer lægges sammen med den efterfølgende afstand til hejs. Eksempel: 10 m kran + 25 m på jorden = 35 m og 14 %. Ved 20 m videre på stilladset kommer 7 % oveni, fordi der er 10 m uden ekstra stilladstillæg i dette forløb. Samlet 21 %.</p><h3>Efter 55 m</h3><p>Med hjul fortsætter +7 procentpoint pr. påbegyndt 20 m over 55 m. Uden hjul kræver afregningen afklaring: A6 nævner hjul, pkt. 27.1.c gør ikke. Vælg en tydeligt vejledende beregning eller dokumentér en særskilt aftale.</p><h3>Videre på stilladset</h3><p>Bil til hejs højst 25 m: først ekstra stilladstillæg over 15 m fra hejs. Bil til hejs over 25 m: først ekstra stilladstillæg over 10 m fra hejs. Derefter +7 procentpoint pr. påbegyndt 10 m, lagt til satsen frem til hejs.</p><h3>Husmodellen</h3><p>Orange viser kran, grønt viser den videre transport på jorden, og det mørke spor følger ruten til et eksempelpunkt i den valgte zone. Rektanglet er en transportlinje, ikke en opmåling af materiel. Begge veje bruger den korteste af de to åbne ruter. Én vej spærrer den anden adgang lige ved starten. Flere hejs og spærringer kan angives under husmodellens avancerede ruter. Andre husformer opgøres i Egne transportlinjer.</p><p>Hvidbog A6 kræver, at flere mulige transportveje afklares før opgaven. Appen vælger ikke en længere rute for at øge tillægget.</p></section><section class="panel guide-panel"><h2>Hvad indeholder fanerne?</h2><div class="coverage">${CALCULATORS.map(c=>`<div class="coverage-item"><div><strong>${escape(c.title)}</strong><small>${escape(c.ref)}</small></div><button class="link-button" data-open-calc="${c.id}">Åbn ↗</button></div>`).join('')}</div></section><section class="panel guide-panel"><h2>Kilder, data & installation</h2><h3>Priskurant og hvidbog</h3><p><a href="./sources/HP3-Provinsen-2026.pdf" target="_blank" rel="noopener">Åbn projektets HP3 Provinsen 2026 ↗</a><br><a href="./sources/Hvidbog-2025.pdf" target="_blank" rel="noopener">Åbn projektets Hvidbog 2025 ↗</a><br><a href="${SOURCE_URL}" target="_blank" rel="noopener">DI · Officiel HP3 Provinsen 2025 ↗</a><br><a href="https://www.danskindustri.dk/DownloadDocument?docid=222595&id=580131" target="_blank" rel="noopener">DI · Hvidbog for stilladsarbejde 2025 ↗</a><br><a href="https://www.danskindustri.dk/medlemsforeninger/stilladssektionen/priskuranter-og-hvidbog/" target="_blank" rel="noopener">DI · Indgang til gældende dokumenter ↗</a></p><p>Din PDF beskriver sig selv som vejledende. Den officielle 2025-udgave angiver +2,7 % fra 1. januar 2026 og +2,5 % fra 1. marts 2027. Appens kronebeløb er låst til den viste 2026-periode og opdateres ikke automatisk.</p><h3>Afklaringer står synligt</h3><p>Ved A8-forhold, manglende teltgrundpriser og uafklaret afrunding mellem 3 m-punkter over 52 m vises ingen opdigtet standardsats. Brug den relevante aftale eller afklaring.</p><h3>Dine oplysninger</h3><p>Beregningsdata gemmes i denne browser / app på enheden. Ingen analyseværktøjer, annoncer, konto til selve beregneren eller eksterne beregningskald. Det private weblink kan kræve dit ChatGPT-login. En sikkerhedskopi er en fil med dine egne indtastninger.</p><h3>Brug på telefonen</h3><p>Webudgaven kan føjes til startskærmen. Beregneren og gemte data kan bruges offline, når appfilerne er hentet. Eksterne kilder og første åbning kræver forbindelse. Denne version er endnu ikke udgivet i Google Play eller App Store.</p><button class="btn secondary small" data-action="install">Vis installationsvejledning ↗</button></section></div>`;}

function showInstall(){const native=isNative();$('#dialog-content').innerHTML=`<h2>${native?'Du bruger appen':'Brug Akkordklar på telefonen'}</h2>${installPrompt?'<p>Din browser understøtter installation direkte.</p><button class="btn" data-action="install-now">Installér Akkordklar</button>':''}<h3>Android · Chrome</h3><ol><li>Åbn appens link i Chrome.</li><li>Tryk på ⋮-menuen.</li><li>Vælg “Føj til startskærm” eller “Installér app”.</li></ol><h3>iPhone · Safari</h3><ol><li>Åbn appens link i Safari.</li><li>Tryk på Del.</li><li>Vælg “Føj til hjemmeskærm”.</li></ol><p>Webudgaven er en fungerende beregner. Udgivelse i Google Play og App Store mangler stadig signerede builds, udviklerkonti, test og butikkernes godkendelse.</p>`;$('#help-dialog').showModal();}

document.addEventListener('click',async e=>{if(state.active==='transport'&&tallyView.handleClick(e))return;if(e.target.closest('[data-back-tally]')){state.transport.entry='sheet';renderTransport();persist();return;}if(!state.transport.legacyMode&&transportView.handleClick(e))return;const el=e.target.closest('button,[data-zone]');if(!el)return;
 if(el.dataset.tab){switchTab(el.dataset.tab);return;}
 if(el.dataset.sub){state.sub[state.active]=el.dataset.sub;render();return;}
 if(el.dataset.openCalc){const c=CALCULATORS.find(c=>c.id===el.dataset.openCalc);state.sub[c.group]=c.id;switchTab(c.group);return;}
 if(el.dataset.mode){if(el.dataset.mode==='house')state.transport.legacyMode=false;state.transport.mode=el.dataset.mode;renderTransport();persist();return;}
 if(el.dataset.route||el.dataset.stage){const k=el.dataset.route?'route':'stage';state.transport.config[k]=el.dataset[k];resetZonePrices();renderTransport();persist();return;}
 if(el.dataset.zone){state.transport.selected=Number(el.dataset.zone);updateHouse(true);$$('[data-zone-row]').forEach(r=>r.classList.toggle('selected',r.dataset.zoneRow===el.dataset.zone));persist();return;}
 if(el.dataset.removeManual){state.transport.manual=state.transport.manual.filter(r=>r.id!==el.dataset.removeManual);renderTransport();persist();return;}
 if(el.dataset.removeLedger){const index=state.ledger.findIndex(r=>r.id===el.dataset.removeLedger);if(index<0)return;const [removed]=state.ledger.splice(index,1);renderOverview();nav();persist();toast('Linjen er fjernet. Du kan gemme beregningen igen fra fanen.');return;}
 const action=el.dataset.action;
 if(action==='new-flow'){state.transport.legacyMode=false;renderTransport();persist();return;}
 if(action==='theme'){state.theme=state.theme==='dark'?'light':'dark';applyTheme();persist();return;}
 if(action==='new-project'){newProject();return;}
 if(action==='copy-project'){copyProject();return;}
 if(action==='guide')switchTab('guide');
 if(action==='save-house')saveHouse();
 if(action==='save-manual')saveManual();
 if(action==='save-calc')saveCalc(el.dataset.calcId);
 if(action==='add-manual'){state.transport.manual.push({id:uid(),name:`Felt ${state.transport.manual.length+1}`,ground:25,crane:0,craneDirection:'left',source:'truck',scaffold:0,method:'manual',stage:'ground',base:''});renderTransport();persist();}
 if(action==='example-c2'){state.transport.mode='manual';const row={id:uid(),name:'Eksempel · figur C2',ground:25,crane:10,craneDirection:'left',source:'truck',scaffold:20,method:'manual',stage:'scaffold',base:''};state.transport.manual.push(row);renderTransport();persist();$(`[data-manual-card="${escape(row.id)}"]`)?.scrollIntoView({block:'start',behavior:'smooth'});}
 if(action==='share')await shareReport();
 if(action==='print'){if(isNative()){const html='<!doctype html><html lang="da"><meta charset="utf-8"><title>Akkordklar · beregningsark</title><style>body{font:14px/1.7 Arial,sans-serif;color:#132b43;margin:28px}pre{white-space:pre-wrap;overflow-wrap:anywhere}h1{font-size:24px}@media print{body{margin:12mm}}</style><h1>Akkordklar · beregningsark</h1><pre>'+escape(reportText())+'</pre></html>';await download(new Blob([html],{type:'text/html;charset=utf-8'}),'akkordklar-beregningsark.html');}else{renderOverview();window.print();}}
 if(action==='backup'){persist();await download(new Blob([JSON.stringify(backupPayload(state),null,2)],{type:'application/json'}),'akkordklar-projekter.json');toast('Alle projekter, indtastninger og gemte beregninger er med i sikkerhedskopien.');}
 if(action==='import')$('#import-file').click();
 if(action==='install')showInstall();
 if(action==='close-dialog')$('#help-dialog').close();
 if(action==='install-now'&&installPrompt){await installPrompt.prompt();installPrompt=null;$('#help-dialog').close();}
});
function resetZonePrices(){if(Object.keys(state.transport.amounts).length)state.transport.pricesReset=true;state.transport.amounts={};state.transport.selected=1;state.transport.agreed=false;const agreed=$('[data-h-agreed]');if(agreed)agreed.checked=false;}
document.addEventListener('input',e=>{if(state.active==='transport'&&tallyView.handleInput(e))return;if(!state.transport.legacyMode&&transportView.handleInput(e))return;const el=e.target;
 if(el.hasAttribute('data-project-select')){switchProject(el.value);return;}
 if(el.hasAttribute('data-price-mode')){const p=state.transport.pricing;p.mode=el.value;if(p.mode==='sides'&&!Object.keys(p.shares).length&&houseResult)p.shares=defaultShares(houseResult.zones);renderTransport();persist();return;}
 if(el.dataset.priceField){state.transport.pricing[el.dataset.priceField]=el.value;if(houseResult)updateHouse(true);persist();return;}
 if(el.dataset.priceShare){state.transport.pricing.shares[el.dataset.priceShare]=el.value;if(houseResult)updateHouse(true);persist();return;}

 if(el.dataset.hField){const key=el.dataset.hField;state.transport.config[key]=el.type==='checkbox'?el.checked:el.value;if(key==='craneDirection'){updateHouse(true);}else{resetZonePrices();updateHouse(false);}persist();return;}
 if(el.hasAttribute('data-h-wheels')){state.transport.config.method=el.checked?'wheels':'manual';resetZonePrices();updateHouse(false);persist();return;}
 if(el.hasAttribute('data-h-agreed')){state.transport.agreed=el.checked;if(houseResult)updateHouseTotal(houseResult);persist();return;}
 if(el.dataset.zoneBase){state.transport.amounts[el.dataset.zoneBase]=el.value;if(houseResult)updateHouse(true);persist();return;}
 if(el.dataset.manualField){const row=state.transport.manual.find(r=>r.id===el.dataset.manualId);row[el.dataset.manualField]=el.value;updateManual();persist();return;}
 if(el.dataset.calcField){const c=CALCULATORS.find(c=>c.id===el.dataset.calc);calcValues(c)[el.dataset.calcField]=el.type==='checkbox'?el.checked:el.value;updateGeneric(c);persist();return;}
 if(el.dataset.job){state[el.dataset.job]=el.value;persist();return;}
 if(el.dataset.annotation){const row=state.ledger.find(r=>r.id===el.dataset.annotation);if(row)row.annotation=el.value;const print=el.nextElementSibling;if(print)print.textContent=el.value;persist();}
});
document.addEventListener('keydown',e=>{const el=e.target.closest('[data-zone]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click();}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw new Error('Sikkerhedskopien er for stor. Maks. 5 MB.');const value=parseBackup(JSON.parse(await file.text()));persist();if(value.legacy){state.ledger.push(...value.ledger.map(l=>({...l,id:uid()})));if(!state.jobName)state.jobName=value.jobName;if(!state.jobNotes)state.jobNotes=value.jobNotes;toast('Tidligere beregningsark er tilføjet. Eksisterende arbejde er bevaret.');}else{const imported=value.projects.length?value.projects:[{name:value.current.jobName||'Importeret opgave',data:value.current}];for(const p of imported)state.projects.push({id:uid(),name:p.name,updated:new Date().toISOString(),data:structuredClone(p.data)});toast(`${imported.length} projekter er importeret som nye kopier.`);}switchTab('overview');}catch(err){toast(`Kunne ikke åbne filen: ${err.message}`);}finally{e.target.value='';}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
if('serviceWorker' in navigator&&/^https?:/.test(location.protocol)&&!isNative()){let reloading=false;const controlled=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(controlled&&!reloading){reloading=true;persist();location.reload();}});navigator.serviceWorker.register('./sw.js').catch(()=>{});}
if(location.hash&&GROUPS.some(g=>`#${g.id}`===location.hash))state.active=location.hash.slice(1);
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(GROUPS.some(g=>g.id===id)){state.active=id;render();}});
applyTheme();
render();
if(state.transport.legacyMode&&state.transport.mode==='house'&&houseResult)updateHouseTotal(houseResult);
